/* Board (feed + profile grid) and admin screens. Loaded after app.js and shares its globals
   (data, mutate, render, esc, icon, $, toast, me, isAdmin, personName, canEdit, view, profileEmail). */
(function(){
'use strict';
const D=()=>window.MoaDrive;
Object.assign(paths,{image:'M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm3.5 7a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3ZM21 15l-5-5L5 21',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm13 10v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',clip:'m21 11-8.5 8.5a5 5 0 0 1-7-7L14 4a3.5 3.5 0 0 1 5 5l-8.5 8.5a2 2 0 0 1-3-3L15 7',trash:'M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Zm0 0v6h6',back:'m15 18-6-6 6-6',layers:'m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5'});
const palette=['#5b9cf0','#45b38f','#f08a5b','#c58bf0','#f0b13c','#ef6f8e','#3fb6c9','#7c8cf0'];
const tint=s=>palette[[...(s||'')].reduce((n,c)=>n+c.charCodeAt(0),0)%palette.length];
const initial=email=>esc((personName(email)||'?').trim().slice(0,1).toUpperCase());
const avatar=(email,cls='')=>`<span class="avatar round ${cls}" style="background:${tint(email)}22;color:${tint(email)}">${initial(email)}</span>`;
function ago(iso){const t=new Date(iso),s=(Date.now()-t)/1000;if(s<60)return '방금';if(s<3600)return Math.floor(s/60)+'분 전';if(s<86400)return Math.floor(s/3600)+'시간 전';if(s<604800)return Math.floor(s/86400)+'일 전';return `${t.getFullYear()}.${t.getMonth()+1}.${t.getDate()}`;}
const size=n=>n>1048576?(n/1048576).toFixed(1)+'MB':Math.max(1,Math.round(n/1024))+'KB';
const posts=()=>[...data.posts].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
const people=()=>[...new Set([D().info().admin,...data.members.map(m=>m.email),...data.posts.map(p=>p.owner)].filter(Boolean))];
let pending=[],uploading=false;

/* ---------- media (Drive files, cached on the device) ---------- */
const urls=new Map();let store=null;
function mediaUrl(id){if(urls.has(id))return urls.get(id);const p=(async()=>{const key='https://media.calendar.invalid/'+encodeURIComponent(id);try{store=store||await caches.open('calendar-media-v1');const hit=await store.match(key);if(hit)return URL.createObjectURL(await hit.blob());}catch(_){}const blob=await D().media(id);try{await store?.put(key,new Response(blob));}catch(_){}return URL.createObjectURL(blob);})();urls.set(id,p);p.catch(()=>urls.delete(id));return p;}
// Load images a few at a time so a long feed does not fire dozens of Drive requests at once.
const queue=[];let active=0;
function pump(){while(active<4&&queue.length){const img=queue.shift();if(!img.isConnected)continue;active++;mediaUrl(img.dataset.media).then(u=>{img.src=u;img.classList.add('loaded');}).catch(()=>{img.classList.add('failed');img.alt='사진을 불러오려면 Google 다시 연결';}).finally(()=>{active--;pump();});}}
function hydrate(root=document){root.querySelectorAll('img[data-media]:not([src]):not(.queued)').forEach(img=>{img.classList.add('queued');img.loading='lazy';queue.push(img);});pump();}

/* ---------- image compression before upload ---------- */
async function bitmap(file){try{return await createImageBitmap(file,{imageOrientation:'from-image'});}catch(_){const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();return img;}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}}
async function jpeg(src,max,quality){const w=src.width,h=src.height,k=Math.min(1,max/Math.max(w,h)),c=document.createElement('canvas');c.width=Math.round(w*k);c.height=Math.round(h*k);const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(src,0,0,c.width,c.height);return new Promise((ok,fail)=>c.toBlob(b=>b?ok(b):fail(Error('사진을 변환하지 못했습니다.')),'image/jpeg',quality));}

/* ---------- views ---------- */
function postCard(p,full=false){const imgs=p.files.filter(f=>f.image),files=p.files.filter(f=>!f.image);
 return `<article class="post panel"><header class="post-head"><button class="post-author" data-action="open-profile" data-email="${esc(p.owner)}">${avatar(p.owner)}<span><b>${esc(personName(p.owner))}</b><small>${ago(p.createdAt)}</small></span></button>${canEdit(p)?`<button class="icon-button" data-action="delete-post" data-id="${esc(p.id)}" aria-label="게시글 삭제">${icon('trash')}</button>`:''}</header>
 ${imgs.length?`<div class="carousel"><div class="slides">${imgs.map((f,i)=>`<div class="slide"><img data-media="${esc(f.id)}" alt="${esc(personName(p.owner))}의 사진 ${i+1}"></div>`).join('')}</div>${imgs.length>1?`<span class="slide-count">1/${imgs.length}</span><div class="dots">${imgs.map((_,i)=>`<i class="${i?'':'on'}"></i>`).join('')}</div>`:''}</div>`:''}
 ${p.text?`<p class="post-text ${imgs.length?'':'big'}"><b>${esc(personName(p.owner))}</b> ${esc(p.text)}</p>`:''}
 ${files.length?`<ul class="attachments">${files.map(f=>`<li><button data-action="download-file" data-id="${esc(f.id)}" data-name="${esc(f.name)}">${icon('file')}<span>${esc(f.name)}</span><small>${size(f.size)}</small></button></li>`).join('')}</ul>`:''}</article>`;}
function composer(){const mine=me();return `<form class="composer panel" id="postForm"><div class="composer-row">${avatar(mine)}<textarea name="text" id="postText" maxlength="4000" placeholder="${esc(personName(mine))}님, 오늘 어떤 일이 있었나요?"></textarea></div><div class="previews">${pending.map((f,i)=>`<span class="preview">${f.url?`<img src="${f.url}" alt="">`:`${icon('file')}<small>${esc(f.file.name)}</small>`}<button type="button" data-action="unpick" data-index="${i}" aria-label="빼기">×</button></span>`).join('')}</div><div class="composer-actions"><label class="button subtle pick">${icon('image')}사진 · 파일<input type="file" id="postFiles" multiple hidden></label><button class="button primary" type="submit" ${uploading?'disabled':''}>${uploading?'올리는 중…':'게시하기'}</button></div></form>`;}
function renderBoard(){const list=posts(),everyone=people();
 $('#content').innerHTML=`<div class="board"><div class="stories">${everyone.map(e=>`<button class="story" data-action="open-profile" data-email="${esc(e)}">${avatar(e,'ring')}<small>${e===me()?'내 프로필':esc(personName(e))}</small></button>`).join('')}</div>${composer()}<div class="feed">${list.map(p=>postCard(p)).join('')||'<div class="empty-state"><h3>첫 이야기를 남겨보세요</h3><p>사진이나 파일, 짧은 글을 올리면<br>초대한 사람들과 함께 볼 수 있어요.</p></div>'}</div></div>`;}
function renderProfile(){const email=profileEmail||me(),list=posts().filter(p=>p.owner===email),photos=list.reduce((n,p)=>n+p.files.filter(f=>f.image).length,0),groups=data.groups.filter(g=>g.members.includes(email));
 $('#content').innerHTML=`<div class="board"><button class="text-button back" data-view="board">${icon('back')}피드로</button><section class="profile-head">${avatar(email,'xl ring')}<div class="profile-info"><h2>${esc(personName(email))}</h2><p>${esc(email)}</p><div class="profile-stats"><span><b>${list.length}</b>게시물</span><span><b>${photos}</b>사진</span><span><b>${groups.length}</b>그룹</span></div>${groups.length?`<div class="profile-groups">${groups.map(g=>`<span class="badge" style="background:${esc(g.color)}22;color:${esc(g.color)}">${esc(g.title)}</span>`).join('')}</div>`:''}</div></section>
 <div class="profile-grid">${list.map(p=>{const img=p.files.find(f=>f.image),n=p.files.filter(f=>f.image).length;return `<button class="tile" data-action="open-post" data-id="${esc(p.id)}" aria-label="게시글 보기">${img?`<img data-media="${esc(img.thumb||img.id)}" alt="">`:`<span class="tile-text" style="background:linear-gradient(145deg,${tint(p.id)}33,${tint(p.owner)}22)">${esc(p.text.slice(0,60)||'파일')}</span>`}${n>1?`<span class="multi">${icon('layers')}</span>`:''}</button>`;}).join('')}</div>${list.length?'':'<p class="task-help" style="text-align:center">아직 올린 게시물이 없어요.</p>'}</div>`;}
function renderAdmin(){if(!isAdmin()){$('#content').innerHTML='<div class="empty-state"><h3>관리자만 볼 수 있어요</h3></div>';return;}const adminEmail=D().info().admin,members=[{email:adminEmail,role:'admin'},...data.members.filter(m=>m.email!==adminEmail)];
 $('#content').innerHTML=`<div class="admin-grid"><section class="panel admin-card"><h3>${icon('users')}멤버</h3><form id="memberForm" class="inline-form"><input type="email" name="email" required placeholder="초대할 Google 이메일" aria-label="초대할 이메일"><button class="button primary" type="submit">초대</button></form><p class="form-note">초대하면 공유 공간 폴더가 그 계정에 공유됩니다. Google Cloud Console의 <b>테스트 사용자</b>에도 같은 이메일을 넣어야 로그인할 수 있어요.</p><ul class="member-list">${members.map(m=>`<li>${avatar(m.email)}<div><b>${esc(personName(m.email))}</b><small>${esc(m.email)}</small></div><span class="badge">${m.role==='admin'?'관리자':'멤버'}</span>${m.role==='admin'?'':`<button class="text-button" data-action="remove-member" data-email="${esc(m.email)}">내보내기</button>`}</li>`).join('')}</ul></section>
 <section class="panel admin-card"><h3>${icon('layers')}그룹</h3><p class="form-note">일정을 저장할 때 ‘공유’에서 그룹을 고르면 그 그룹 멤버의 캘린더에 함께 보입니다.</p><ul class="member-list">${data.groups.map(g=>`<li><span class="group-dot" style="background:${esc(g.color)}"></span><div><b>${esc(g.title)}</b><small>${g.members.map(x=>esc(personName(x))).join(', ')||'멤버 없음'}</small></div><button class="text-button" data-action="edit-group" data-id="${esc(g.id)}">편집</button></li>`).join('')||'<li class="muted">아직 그룹이 없어요.</li>'}</ul><button class="button full" data-action="new-group">${icon('plus')}그룹 만들기</button></section>
 <section class="panel admin-card"><h3>${icon('calendar')}모든 사람의 일정</h3><p class="form-note">관리자는 캘린더 위쪽 선택 상자에서 ‘모든 사람’ 또는 특정 멤버를 골라 일정을 볼 수 있어요. 다른 사람의 일정도 열어서 고칠 수 있습니다.</p><button class="button" data-action="view-all">모든 사람의 일정 보기</button></section></div>`;}
function groupDialog(id=''){const g=id?data.groups.find(x=>x.id===id):null,d=$('#groupDialog'),list=people();
 d.innerHTML=`<form id="groupForm" data-id="${esc(id)}"><div class="dialog-header"><h2>${g?'그룹 편집':'새 그룹'}</h2><button class="icon-button" type="button" data-action="close-group" aria-label="닫기">${icon('close')}</button></div><div class="form-body"><div class="field-row">${field('그룹 이름','title','text',g?.title||'','required maxlength="200" placeholder="예: 가족, 스터디"')}${field('색상','color','color',g?.color||palette[data.groups.length%palette.length])}</div><div class="field"><label>멤버</label><div class="check-list">${list.map(e=>`<label class="check"><input type="checkbox" name="members" value="${esc(e)}" ${g?.members.includes(e)?'checked':''}>${avatar(e)}<span>${esc(personName(e))}<small>${esc(e)}</small></span></label>`).join('')}</div></div><div class="form-error" id="groupError" role="alert"></div></div><div class="dialog-footer">${g?'<button type="button" class="button danger" data-action="delete-group">삭제</button>':''}<div class="right"><button type="button" class="button" data-action="close-group">취소</button><button class="button primary" type="submit">저장하기</button></div></div></form>`;fillIcons(d);d.showModal();}
function openPost(id){const p=data.posts.find(x=>x.id===id);if(!p)return;const d=$('#postDialog');d.innerHTML=`<div class="post-dialog"><button class="icon-button close-post" data-action="close-post" aria-label="닫기">${icon('close')}</button>${postCard(p,true)}</div>`;d.showModal();hydrate(d);}

/* ---------- actions ---------- */
async function submitPost(form){if(uploading)return;const text=form.text.value.trim();if(!text&&!pending.length){toast('글이나 사진을 넣어주세요.',true);return;}if(pending.length&&!D().info().connected){toast('사진·파일을 올리려면 Google을 다시 연결해주세요.',true);D().connect();return;}
 uploading=true;const btn=form.querySelector('[type=submit]');btn.disabled=true;const files=[];
 try{for(let i=0;i<pending.length;i++){const f=pending[i].file;btn.textContent=`올리는 중 ${i+1}/${pending.length}`;
  if(f.type.startsWith('image/')&&!/gif|svg/.test(f.type)){const src=await bitmap(f),[big,small]=[await jpeg(src,1600,.82),await jpeg(src,480,.72)];const base=f.name.replace(/\.[^.]+$/,'')||'photo';const id=await D().uploadFile(big,base+'.jpg','image/jpeg'),thumb=await D().uploadFile(small,base+'-thumb.jpg','image/jpeg');files.push({id,thumb,name:base+'.jpg',mime:'image/jpeg',size:big.size,image:true});}
  else{if(f.size>25*1024*1024)throw Error(f.name+' 파일이 25MB보다 큽니다.');const id=await D().uploadFile(f,f.name,f.type||'application/octet-stream');files.push({id,thumb:'',name:f.name.slice(0,300),mime:f.type||'application/octet-stream',size:f.size,image:f.type.startsWith('image/')});}}
  const post={id:crypto.randomUUID(),owner:me(),text,createdAt:new Date().toISOString(),files};
  for(const p of pending)if(p.url)URL.revokeObjectURL(p.url);pending=[];uploading=false;if(mutate(d=>d.posts.push(post)))toast('게시했어요.');}
 catch(e){uploading=false;btn.disabled=false;btn.textContent='게시하기';toast('올리지 못했습니다. '+(e.message||''),true);for(const f of files){D().trash(f.id).catch(()=>{});if(f.thumb)D().trash(f.thumb).catch(()=>{});}}}
function pick(input){const room=10-pending.length,chosen=[...input.files].slice(0,room);if(input.files.length>room)toast('한 게시글에 최대 10개까지 올릴 수 있어요.',true);for(const file of chosen)pending.push({file,url:file.type.startsWith('image/')?URL.createObjectURL(file):''});input.value='';const text=$('#postText')?.value||'';render();if($('#postText'))$('#postText').value=text;}
async function download(id,name){try{toast('파일을 받는 중…');const blob=await D().media(id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name||'file';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch(e){toast('받지 못했습니다. '+e.message,true);}}
async function invite(email){email=email.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+$/.test(email)){toast('이메일을 확인해주세요.',true);return;}if(data.members.some(m=>m.email===email)||email===D().info().admin){toast('이미 초대한 사람입니다.',true);return;}if(!D().info().connected){toast('초대하려면 Google을 다시 연결해주세요.',true);D().connect();return;}
 try{await D().share(email);if(mutate(d=>d.members.push({id:email,email,role:'member'})))toast(email+' 님을 초대했어요. 테스트 사용자 등록도 잊지 마세요.');}catch(e){toast('초대하지 못했습니다. '+e.message,true);}}
function removeMember(email){confirmAction('멤버를 내보낼까요?',`${personName(email)} (${email}) 님의 공유 폴더 접근을 끊고 모든 그룹에서 뺍니다. 그 사람이 남긴 일정과 글은 남아 있습니다.`,async()=>{try{if(D().info().connected)await D().unshare(email);else toast('Google 연결 후 Drive 공유도 해제해주세요.',true);}catch(e){toast('Drive 공유 해제 실패: '+e.message,true);}mutate(d=>{d.members=d.members.filter(m=>m.email!==email);d.groups.forEach(g=>{g.members=g.members.filter(x=>x!==email);});});},'내보내기');}
function saveGroup(form){const id=form.dataset.id||crypto.randomUUID(),title=form.title.value.trim(),color=form.color.value,members=[...form.querySelectorAll('[name=members]:checked')].map(x=>x.value);if(!title){$('#groupError').textContent='그룹 이름을 입력해주세요.';return;}if(mutate(d=>{const g={id,title,color,members},at=d.groups.findIndex(x=>x.id===id);if(at<0)d.groups.push(g);else d.groups[at]=g;})){$('#groupDialog').close();toast('그룹을 저장했어요.');}}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='open-profile'){profileEmail=el.dataset.email;view='profile';render();window.scrollTo(0,0);}
 else if(a==='open-post')openPost(el.dataset.id);
 else if(a==='close-post')$('#postDialog').close();
 else if(a==='delete-post'){const p=data.posts.find(x=>x.id===el.dataset.id);confirmAction('게시글을 삭제할까요?','삭제하면 되돌릴 수 없습니다.',()=>{if(mutate(d=>{d.posts=d.posts.filter(x=>x.id!==p.id);})){$('#postDialog').open&&$('#postDialog').close();if(p.owner===me())for(const f of p.files){D().trash(f.id).catch(()=>{});if(f.thumb)D().trash(f.thumb).catch(()=>{});}toast('삭제했어요.');}});}
 else if(a==='download-file')download(el.dataset.id,el.dataset.name);
 else if(a==='unpick'){const [f]=pending.splice(Number(el.dataset.index),1);if(f?.url)URL.revokeObjectURL(f.url);const text=$('#postText')?.value||'';render();if($('#postText'))$('#postText').value=text;}
 else if(a==='focus-composer'){if(view!=='board'){view='board';render();}setTimeout(()=>$('#postText')?.focus(),30);}
 else if(a==='new-group')groupDialog();
 else if(a==='edit-group')groupDialog(el.dataset.id);
 else if(a==='close-group')$('#groupDialog').close();
 else if(a==='delete-group'){const id=$('#groupForm').dataset.id;confirmAction('그룹을 삭제할까요?','이 그룹에 공유한 일정은 작성자만 볼 수 있게 됩니다.',()=>{if(mutate(d=>{d.groups=d.groups.filter(g=>g.id!==id);}))$('#groupDialog').close();});}
 else if(a==='remove-member')removeMember(el.dataset.email);
 else if(a==='view-all'){personFilter='all';view='calendar';render();}
});
document.addEventListener('change',e=>{if(e.target.id==='postFiles')pick(e.target);});
document.addEventListener('submit',e=>{if(e.target.id==='postForm'){e.preventDefault();submitPost(e.target);}else if(e.target.id==='memberForm'){e.preventDefault();invite(e.target.email.value);}else if(e.target.id==='groupForm'){e.preventDefault();saveGroup(e.target);}});
// Carousel position indicator.
document.addEventListener('scroll',e=>{const s=e.target;if(!(s instanceof Element)||!s.classList.contains('slides'))return;const i=Math.round(s.scrollLeft/s.clientWidth),c=s.parentElement;c.querySelectorAll('.dots i').forEach((d,k)=>d.classList.toggle('on',k===i));const n=c.querySelector('.slide-count');if(n)n.textContent=`${i+1}/${s.children.length}`;},true);
window.Social={render(v){if(v==='board')renderBoard();else if(v==='profile')renderProfile();else renderAdmin();},after(){hydrate();}};
fillIcons();if(['board','profile','admin'].includes(view))render();
})();
